import{_ as i,o as t,c as a,a2 as o}from"./chunks/framework.BKjcr3i4.js";const s="/docs/guide/editor-workbench/tabs-shortcuts-before.png",r="/docs/guide/editor-workbench/tabs-shortcuts-after.png",d="/docs/guide/editor-workbench/pasted-images-fullpage.png",l="/docs/guide/editor-workbench/pasted-images-toolbar.png",f=JSON.parse('{"title":"Editor Workbench","description":"","frontmatter":{"title":"Editor Workbench","audience":"public","status":"draft","owner":"core-team"},"headers":[],"relativePath":"guide/editor-workbench.md","filePath":"guide/editor-workbench.md"}'),n={name:"guide/editor-workbench.md"};function c(h,e,u,p,g,m){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="editor-workbench" tabindex="-1">Editor Workbench <a class="header-anchor" href="#editor-workbench" aria-label="Permalink to &quot;Editor Workbench&quot;">​</a></h1><p>This section groups the workflows for the OUi editor experience:</p><ul><li>source authoring in the code editor</li><li>structure-first visual editing in the SVG preview</li><li>export and clipboard actions for downstream design tools</li></ul><h2 id="code-editor" tabindex="-1">Code Editor <a class="header-anchor" href="#code-editor" aria-label="Permalink to &quot;Code Editor&quot;">​</a></h2><p>The code editor is the source of truth for every screen. It provides:</p><ul><li>syntax-aware highlighting and visual affordances for directives, components, and tokens</li><li>multiline editing for props and structured blocks</li><li>sample-aware navigation with canonical sample URLs</li><li>source formatting and search helpers</li></ul><p>For details about the visual syntax layer used by the editor, see <a href="/docs/guide/editor-visual-syntax.html">Editor Visual Syntax</a>.</p><h2 id="visual-editor-and-svg-preview" tabindex="-1">Visual Editor and SVG Preview <a class="header-anchor" href="#visual-editor-and-svg-preview" aria-label="Permalink to &quot;Visual Editor and SVG Preview&quot;">​</a></h2><p>The visual side of the playground renders the same AST through the SVG renderer and keeps selection synchronized with source lines.</p><p>Core behaviors:</p><ul><li>click a node in preview to focus the matching source range</li><li>inspect and highlight layout or component targets</li><li>use fullscreen and fit modes for larger compositions</li></ul><p>For the docs renderer behavior, see <a href="/docs/guide/live-preview.html">Live Preview</a>.</p><h2 id="design-mode-tabs-and-navigation-lists" tabindex="-1">Design Mode: Tabs and Navigation Lists <a class="header-anchor" href="#design-mode-tabs-and-navigation-lists" aria-label="Permalink to &quot;Design Mode: Tabs and Navigation Lists&quot;">​</a></h2><p>When you work with <code>Tab</code> or <code>NavItem</code> groups in Design Mode, the preview exposes quick controls to speed up list editing:</p><ul><li><code>+ Tab</code> adds a new <code>Tab</code> item inside the current tabs group.</li><li><code>+ NavItem</code> adds a new <code>NavItem</code> item inside the current navigation group.</li></ul><p>After insertion, a contextual shortcut hint appears near the inserted component and auto-hides after a few seconds. You can disable future hints with <code>Don&#39;t show again</code> in that hint panel.</p><h3 id="keyboard-shortcuts-for-group-editing" tabindex="-1">Keyboard Shortcuts for Group Editing <a class="header-anchor" href="#keyboard-shortcuts-for-group-editing" aria-label="Permalink to &quot;Keyboard Shortcuts for Group Editing&quot;">​</a></h3><p>Use these shortcuts while your selection is inside a <code>Tab</code> or <code>NavItem</code> group:</p><ul><li>Cycle the active item: <ul><li>macOS: <code>Option + Left/Right</code> or <code>Cmd + Left/Right</code></li><li>Windows/Linux: <code>Alt + Left/Right</code></li></ul></li><li>Move the selected item up/down: <ul><li>macOS: <code>Option + Shift + Up/Down</code> or <code>Cmd + Shift + Up/Down</code></li><li>Windows/Linux: <code>Alt + Shift + Up/Down</code></li></ul></li></ul><p>Notes:</p><ul><li>Active state cycling updates <code>Tab.selected</code> or <code>NavItem.active</code> in source.</li><li>Reordering preserves source structure and follows the visible group order.</li><li>For the full shortcut catalog across all components/workflows, see <a href="/docs/guide/keyboard-shortcuts.html">Keyboard Shortcuts</a>.</li></ul><h3 id="visual-walkthrough-tabs-interaction" tabindex="-1">Visual Walkthrough (Tabs Interaction) <a class="header-anchor" href="#visual-walkthrough-tabs-interaction" aria-label="Permalink to &quot;Visual Walkthrough (Tabs Interaction)&quot;">​</a></h3><p>The editor supports a repeatable visual flow for keyboard interactions in tabs/navigation groups:</p><ol><li>Keep the caret inside a <code>Tabs</code>/<code>Tab</code> group to target that component context.</li><li>Use <code>Alt + Left/Right</code> (<code>Cmd + Left/Right</code> on macOS) to cycle the active item.</li><li>Press <code>F1</code> (or <code>Alt + /</code>) to open the shortcut hint panel for the current component.</li></ol><p>Baseline state:</p><div class="docs-shot"><img src="'+s+'" alt="Tabs sample before opening the shortcut hint"></div><p>Shortcut hint and keyboard combo overlay:</p><div class="docs-shot"><img src="'+r+'" alt="Tabs sample showing F1 shortcut hint toast and keyboard combos"></div><h2 id="copying-svg-from-the-preview" tabindex="-1">Copying SVG from the Preview <a class="header-anchor" href="#copying-svg-from-the-preview" aria-label="Permalink to &quot;Copying SVG from the Preview&quot;">​</a></h2><p>You can copy SVG directly from preview selection:</p><ul><li><code>Cmd+Shift+C</code> on macOS</li><li><code>Ctrl+Shift+C</code> on Windows/Linux</li></ul><p>Behavior:</p><ul><li>if a preview node is selected, the editor copies that node as a standalone SVG</li><li>if no preview node is selected, the editor copies the full preview SVG</li></ul><p>This is useful when pasting wireframe fragments into design tools like Figma.</p><h2 id="clipboard-image-paste-and-materialization" tabindex="-1">Clipboard Image Paste and Materialization <a class="header-anchor" href="#clipboard-image-paste-and-materialization" aria-label="Permalink to &quot;Clipboard Image Paste and Materialization&quot;">​</a></h2><p>When you paste an image into the code editor, OUi inserts a markdown image with an embedded data URL so the document remains portable across Playground and VS Code:</p><ul><li><code>![Alt text](data:image/... | border=none width=... height=...)</code></li></ul><div class="docs-shot"><img src="'+d+'" alt="Pasted Images sample in the editor"></div><h3 id="why-this-flow-exists" tabindex="-1">Why this flow exists <a class="header-anchor" href="#why-this-flow-exists" aria-label="Permalink to &quot;Why this flow exists&quot;">​</a></h3><ul><li>preserves visual parity between editors</li><li>keeps pasted screenshots/SVGs portable when sharing source files</li><li>avoids local-only clipboard references that can break across sessions</li></ul><div class="docs-shot" data-focus-source-width="1600" data-focus-source-height="1000" data-focus-x="1348" data-focus-y="14" data-focus-width="52" data-focus-height="50" data-focus-label-x="1229" data-focus-label-y="81" data-focus-label="Materialized copy action" data-lightbox-focus-zoom="2.4"><img src="'+l+`" alt="Toolbar interaction for materialized copy"></div><p>You can also call the same behavior from the browser console:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> window.OUi.export.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">copyMaterializedDoc</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.OUi.export.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">materializePastedImages</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span></code></pre></div><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to &quot;Related Guides&quot;">​</a></h2><ul><li><a href="/docs/guide/authoring.html">Authoring Guide</a></li><li><a href="/docs/guide/quick-start.html">Quick start</a></li><li><a href="/docs/guide/editor-visual-syntax.html">Editor Visual Syntax</a></li><li><a href="/docs/guide/live-preview.html">Live Preview</a></li></ul>`,45)])])}const v=i(n,[["render",c]]);export{f as __pageData,v as default};
